/**
 * Moves every issue from `sourceLabelId` onto `targetLabelId`, then removes the
 * source label. Issues that already carry the target keep exactly one join row.
 * Runs in one transaction so a failure leaves both labels untouched.
 *
 * Returns the number of issues that carried the source label beforehand.
 */
export async function mergeLabelInto(
  orgId: OrgId,
  sourceLabelId: LabelId,
  targetLabelId: LabelId,
): Promise<number> {
  return getDb().transaction((tx) => {
    const issueIds = tx
      .select({ issueId: issueLabels.issueId })
      .from(issueLabels)
      .where(
        and(
          orgPredicate(issueLabels.orgId, orgId),
          eq(issueLabels.labelId, sourceLabelId),
        ),
      )
      .all()
      .map((row) => row.issueId);

    if (issueIds.length > 0) {
      tx.insert(issueLabels)
        .values(
          issueIds.map((issueId) => ({
            orgId,
            issueId,
            labelId: targetLabelId,
          })),
        )
        .onConflictDoNothing()
        .run();
    }

    tx.delete(issueLabels)
      .where(
        and(
          orgPredicate(issueLabels.orgId, orgId),
          eq(issueLabels.labelId, sourceLabelId),
        ),
      )
      .run();
    tx.delete(labels)
      .where(and(orgPredicate(labels.orgId, orgId), eq(labels.id, sourceLabelId)))
      .run();

    return issueIds.length;
  });
}

